549	  get2DCursorLocation(selectionStart: number, skipWrapping?: boolean) {
550	    const lines = skipWrapping ? this._unwrappedTextLines : this._textLines;
551	    let i: number;
552	    for (i = 0; i < lines.length; i++) {
553	      if (selectionStart <= lines[i].length) {
554	        return {
555	          lineIndex: i,
556	          charIndex: selectionStart,
557	        };
558	      }
559	      selectionStart -=
