786	  /**
787	   * measure and return the width of a single character.
788	   * possibly overridden to accommodate different measure logic or
789	   * to hook some external lib for character measurement
790	   * @private
791	   * @param {String} _char, char to be measured
792	   * @param {Object} charStyle style of char to be measured
793	   * @param {String} [previousChar] previous char
794	   * @param {Object} [prevCharStyle] style of previous char
795	   */
796	  _measureChar(
797	    _char: string,
798	    charStyle: CompleteTextStyleDeclaration,
799	    previousChar: string | undefined,
800	    prevCharStyle: CompleteTextStyleDeclaration | Record<string, never>,
801	  ) {
802	    const fontCache = cache.getFontCache(charStyle),
803	      fontDeclaration = this._getFontDeclaration(charStyle),
804	      couple = previousChar + _char,
805	      stylesAreEqual =
806	        previousChar &&
807	        fontDeclaration === this._getFontDeclaration(prevCharStyle),
808	      fontMultiplier = charStyle.fontSize / this.CACHE_FONT_SIZE;
809	    let width: number | undefined,
810	      coupleWidth: number | undefined,
811	      previousWidth: number | undefined,
812	      kernedWidth: number | undefined;
813	
814	    if (previousChar && fontCache.has(previousChar)) {
815	      previousWidth = fontCache.get(previousChar);
816	    }
817	    if (fontCache.has(_char)) {
818	      kernedWidth = width = fontCache.get(_char);
819	    }
820	    if (stylesAreEqual && fontCache.has(couple)) {
821	      coupleWidth = fontCache.get(couple)!;
822	      kernedWidth = coupleWidth - previousWidth!;
823	    }
824	    if (
825	      width === undefined ||
826	      previousWidth === undefined ||
827	      coupleWidth === undefined
828	    ) {
829	      const ctx = getMeasuringContext()!;
830	      // send a TRUE to specify measuring font size CACHE_FONT_SIZE
831	      this._setTextStyles(ctx, charStyle, true);
832	      if (width === undefined) {
833	        kernedWidth = width = ctx.measureText(_char).width;
834	        fontCache.set(_char, width);
835	      }
836	      if (previousWidth === undefined && stylesAreEqual && previousChar) {
837	        previousWidth = ctx.measureText(previousChar).width;
838	        fontCache.set(previousChar, previousWidth);
839	      }
840	      if (stylesAreEqual && coupleWidth === undefined) {
841	        // we can measure the kerning couple and subtract the width of the previous character
842	        coupleWidth = ctx.measureText(couple).width;
843	        fontCache.set(couple, coupleWidth);
844	        // safe to use the non-null since if undefined we defined it before.
845	        kernedWidth = coupleWidth - previousWidth!;
846	      }
847	    }
848	    return {
849	      width: width * fontMultiplier,
850	      kernedWidth: kernedWidth! * fontMultiplier,
851	    };
852	  }
