879	  /**
880	   * measure every grapheme of a line, populating __charBounds
881	   * @param {Number} lineIndex
882	   * @return {Object} object.width total width of characters
883	   * @return {Object} object.numOfSpaces length of chars that match this._reSpacesAndTabs
884	   */
885	  _measureLine(lineIndex: number) {
886	    let width = 0,
887	      prevGrapheme: string | undefined,
888	      graphemeInfo: GraphemeBBox | undefined;
889	
890	    const reverse = this.pathSide === RIGHT,
891	      path = this.path,
892	      line = this._textLines[lineIndex],
893	      llength = line.length,
894	      lineBounds = new Array<GraphemeBBox>(llength);
895	
896	    this.__charBounds[lineIndex] = lineBounds;
897	    for (let i = 0; i < llength; i++) {
898	      const grapheme = line[i];
899	      graphemeInfo = this._getGraphemeBox(grapheme, lineIndex, i, prevGrapheme);
900	      lineBounds[i] = graphemeInfo;
901	      width += graphemeInfo.kernedWidth;
902	      prevGrapheme = grapheme;
903	    }
904	    // this latest bound box represent the last character of the line
905	    // to simplify cursor handling in interactive mode.
906	    lineBounds[llength] = {
907	      left: graphemeInfo ? graphemeInfo.left + graphemeInfo.width : 0,
908	      width: 0,
909	      kernedWidth: 0,
910	      height: this.fontSize,
911	      deltaY: 0,
912	    } as GraphemeBBox;
913	    if (path && path.segmentsInfo) {
914	      let positionInPath = 0;
915	      const totalPathLength =
916	        path.segmentsInfo[path.segmentsInfo.length - 1].length;
917	      switch (this.textAlign) {
918	        case LEFT:
919	          positionInPath = reverse ? totalPathLength - width : 0;
920	          break;
921	        case CENTER:
922	          positionInPath = (totalPathLength - width) / 2;
923	          break;
924	        case RIGHT:
925	          positionInPath = reverse ? 0 : totalPathLength - width;
926	          break;
927	        //todo - add support for justify
928	      }
929	      positionInPath += this.pathStartOffset * (reverse ? -1 : 1);
930	      for (
931	        let i = reverse ? llength - 1 : 0;
932	        reverse ? i >= 0 : i < llength;
933	        reverse ? i-- : i++
934	      ) {
935	        graphemeInfo = lineBounds[i];
936	        if (positionInPath > totalPathLength) {
937	          positionInPath %= totalPathLength;
938	        } else if (positionInPath < 0) {
939	          positionInPath += totalPathLength;
940	        }
941	        // it would probably much faster to send all the grapheme position for a line
942	        // and calculate path position/angle at once.
943	        this._setGraphemeOnPath(positionInPath, graphemeInfo);
944	        positionInPath += graphemeInfo.kernedWidth;
945	      }
946	    }
947	    return { width: width, numOfSpaces: 0 };
948	  }
