1127	  /**
1128	   * @private
1129	   * @param {String} method fillText or strokeText.
1130	   * @param {CanvasRenderingContext2D} ctx Context to render on
1131	   * @param {Array} line Content of the line, splitted in an array by grapheme
1132	   * @param {Number} left
1133	   * @param {Number} top
1134	   * @param {Number} lineIndex
1135	   */
1136	  _renderChars(
1137	    method: 'fillText' | 'strokeText',
1138	    ctx: CanvasRenderingContext2D,
1139	    line: Array<any>,
1140	    left: number,
1141	    top: number,
1142	    lineIndex: number,
1143	  ) {
1144	    const lineHeight = this.getHeightOfLine(lineIndex),
1145	      isJustify = this.textAlign.includes(JUSTIFY),
1146	      path = this.path,
1147	      shortCut =
1148	        !isJustify &&
1149	        this.charSpacing === 0 &&
1150	        this.isEmptyStyles(lineIndex) &&
1151	        !path,
1152	      isLtr = this.direction === 'ltr',
1153	      sign = this.direction === 'ltr' ? 1 : -1,
1154	      // this was changed in the PR #7674
1155	      // currentDirection = ctx.canvas.getAttribute('dir');
1156	      currentDirection = ctx.direction;
1157	
1158	    let actualStyle,
1159	      nextStyle,
1160	      charsToRender = '',
1161	      charBox,
1162	      boxWidth = 0,
1163	      timeToRender,
1164	      drawingLeft;
1165	
1166	    ctx.save();
1167	    if (currentDirection !== this.direction) {
1168	      ctx.canvas.setAttribute('dir', isLtr ? 'ltr' : 'rtl');
1169	      ctx.direction = isLtr ? 'ltr' : 'rtl';
1170	      ctx.textAlign = isLtr ? LEFT : RIGHT;
1171	    }
1172	    top -= (lineHeight * this._fontSizeFraction) / this.lineHeight;
1173	    if (shortCut) {
1174	      // render all the line in one pass without checking
1175	      // drawingLeft = isLtr ? left : left - this.getLineWidth(lineIndex);
1176	      this._renderChar(method, ctx, lineIndex, 0, line.join(''), left, top);
1177	      ctx.restore();
1178	      return;
1179	    }
1180	    for (let i = 0, len = line.length - 1; i <= len; i++) {
1181	      timeToRender = i === len || this.charSpacing || path;
1182	      charsToRender += line[i];
1183	      charBox = this.__charBounds[lineIndex][i] as Required<GraphemeBBox>;
1184	      if (boxWidth === 0) {
1185	        left += sign * (charBox.kernedWidth - charBox.width);
1186	        boxWidth += charBox.width;
1187	      } else {
1188	        boxWidth += charBox.kernedWidth;
1189	      }
1190	      if (isJustify && !timeToRender) {
1191	        if (this._reSpaceAndTab.test(line[i])) {
1192	          timeToRender = true;
1193	        }
1194	      }
1195	      if (!timeToRender) {
1196	        // if we have charSpacing, we render char by char
1197	        actualStyle =
1198	          actualStyle || this.getCompleteStyleDeclaration(lineIndex, i);
1199	        nextStyle = this.getCompleteStyleDeclaration(lineIndex, i + 1);
1200	        timeToRender = hasStyleChanged(actualStyle, nextStyle, false);
1201	      }
1202	      if (timeToRender) {
1203	        if (path) {
1204	          ctx.save();
1205	          ctx.translate(charBox.renderLeft, charBox.renderTop);
1206	          ctx.rotate(charBox.angle);
1207	          this._renderChar(
1208	            method,
1209	            ctx,
1210	            lineIndex,
1211	            i,
1212	            charsToRender,
1213	            -boxWidth / 2,
1214	            0,
1215	          );
1216	          ctx.restore();
1217	        } else {
1218	          drawingLeft = left;
1219	          this._renderChar(
1220	            method,
1221	            ctx,
1222	            lineIndex,
1223	            i,
1224	            charsToRender,
1225	            drawingLeft,
1226	            top,
1227	          );
1228	        }
1229	        charsToRender = '';
1230	        actualStyle = nextStyle;
1231	        left += sign * boxWidth;
1232	        boxWidth = 0;
1233	      }
1234	    }
1235	    ctx.restore();
1236	  }
