1450	   * @return {Number} Line left offset
1451	   */
1452	  _getLineLeftOffset(lineIndex: number): number {
1453	    const lineWidth = this.getLineWidth(lineIndex),
1454	      lineDiff = this.width - lineWidth,
1455	      textAlign = this.textAlign,
1456	      direction = this.direction,
1457	      isEndOfWrapping = this.isEndOfWrapping(lineIndex);
1458	    let leftOffset = 0;
1459	    if (
1460	      textAlign === JUSTIFY ||
1461	      (textAlign === JUSTIFY_CENTER && !isEndOfWrapping) ||
1462	      (textAlign === JUSTIFY_RIGHT && !isEndOfWrapping) ||
1463	      (textAlign === JUSTIFY_LEFT && !isEndOfWrapping)
1464	    ) {
1465	      return 0;
1466	    }
1467	    if (textAlign === CENTER) {
1468	      leftOffset = lineDiff / 2;
1469	    }
1470	    if (textAlign === RIGHT) {
1471	      leftOffset = lineDiff;
1472	    }
1473	    if (textAlign === JUSTIFY_CENTER) {
1474	      leftOffset = lineDiff / 2;
1475	    }
1476	    if (textAlign === JUSTIFY_RIGHT) {
1477	      leftOffset = lineDiff;
1478	    }
1479	    if (direction === 'rtl') {
1480	      if (
1481	        textAlign === RIGHT ||
1482	        textAlign === JUSTIFY ||
1483	        textAlign === JUSTIFY_RIGHT
1484	      ) {
1485	        leftOffset = 0;
1486	      } else if (textAlign === LEFT || textAlign === JUSTIFY_LEFT) {
1487	        leftOffset = -lineDiff;
1488	      } else if (textAlign === CENTER || textAlign === JUSTIFY_CENTER) {
1489	        leftOffset = -lineDiff / 2;
1490	      }
1491	    }
1492	    return leftOffset;
