1564	      const heightOfLine = this.getHeightOfLine(i);
1565	      if (!this[type] && !this.styleHas(type, i)) {
1566	        topOffset += heightOfLine;
1567	        continue;
1568	      }
1569	      const line = this._textLines[i];
1570	      const maxHeight = heightOfLine / this.lineHeight;
1571	      const lineLeftOffset = this._getLineLeftOffset(i);
1572	      let boxStart = 0;
1573	      let boxWidth = 0;
1574	      let lastDecoration = this.getValueOfPropertyAt(i, 0, type);
1575	      let lastFill = this.getValueOfPropertyAt(i, 0, FILL);
1576	      let lastTickness = this.getValueOfPropertyAt(
1577	        i,
1578	        0,
1579	        TEXT_DECORATION_THICKNESS,
1580	      );
1581	      let currentDecoration = lastDecoration;
1582	      let currentFill = lastFill;
1583	      let currentTickness = lastTickness;
1584	      const top = topOffset + maxHeight * (1 - this._fontSizeFraction);
1585	      let size = this.getHeightOfChar(i, 0);
1586	      let dy = this.getValueOfPropertyAt(i, 0, 'deltaY');
1587	      for (let j = 0, jlen = line.length; j < jlen; j++) {
1588	        const charBox = this.__charBounds[i][j] as Required<GraphemeBBox>;
1589	        currentDecoration = this.getValueOfPropertyAt(i, j, type);
1590	        currentFill = this.getValueOfPropertyAt(i, j, FILL);
1591	        currentTickness = this.getValueOfPropertyAt(
1592	          i,
1593	          j,
1594	          TEXT_DECORATION_THICKNESS,
1595	        );
1596	        const currentSize = this.getHeightOfChar(i, j);
1597	        const currentDy = this.getValueOfPropertyAt(i, j, 'deltaY');
1598	        if (path && currentDecoration && currentFill) {
1599	          const finalTickness = (this.fontSize * currentTickness) / 1000;
1600	          ctx.save();
1601	          // bug? verify lastFill is a valid fill here.
1602	          ctx.fillStyle = lastFill as string;
1603	          ctx.translate(charBox.renderLeft, charBox.renderTop);
1604	          ctx.rotate(charBox.angle);
