1606	            -charBox.kernedWidth / 2,
1607	            offsetY * currentSize + currentDy - offsetAligner * finalTickness,
1608	            charBox.kernedWidth,
1609	            finalTickness,
1610	          );
1611	          ctx.restore();
1612	        } else if (
1613	          (currentDecoration !== lastDecoration ||
1614	            currentFill !== lastFill ||
1615	            currentSize !== size ||
1616	            currentTickness !== lastTickness ||
1617	            currentDy !== dy) &&
1618	          boxWidth > 0
1619	        ) {
1620	          const finalTickness = (this.fontSize * lastTickness) / 1000;
1621	          let drawStart = leftOffset + lineLeftOffset + boxStart;
1622	          if (this.direction === 'rtl') {
1623	            drawStart = this.width - drawStart - boxWidth;
1624	          }
1625	          if (lastDecoration && lastFill && lastTickness) {
1626	            // bug? verify lastFill is a valid fill here.
1627	            ctx.fillStyle = lastFill as string;
1628	            ctx.fillRect(
1629	              drawStart,
1630	              top + offsetY * size + dy - offsetAligner * finalTickness,
1631	              boxWidth,
1632	              finalTickness,
1633	            );
1634	          }
1635	          boxStart = charBox.left;
1636	          boxWidth = charBox.width;
1637	          lastDecoration = currentDecoration;
1638	          lastTickness = currentTickness;
1639	          lastFill = currentFill;
1640	          size = currentSize;
1641	          dy = currentDy;
1642	        } else {
1643	          boxWidth += charBox.kernedWidth;
1644	        }
1645	      }
1646	      let drawStart = leftOffset + lineLeftOffset + boxStart;
1647	      if (this.direction === 'rtl') {
1648	        drawStart = this.width - drawStart - boxWidth;
1649	      }
1650	      ctx.fillStyle = currentFill as string;
1651	      const finalTickness = (this.fontSize * currentTickness) / 1000;
1652	      currentDecoration &&
1653	        currentFill &&
1654	        currentTickness &&
