1861	      element,
1862	      FabricText.ATTRIBUTE_NAMES,
1863	      cssRules,
1864	    );
1865	
1866	    const {
1867	      textAnchor = LEFT as typeof LEFT | typeof CENTER | typeof RIGHT,
1868	      textDecoration = '',
1869	      dx = 0,
1870	      dy = 0,
1871	      top = 0,
1872	      left = 0,
1873	      fontSize = DEFAULT_SVG_FONT_SIZE,
1874	      strokeWidth = 1,
1875	      ...restOfOptions
