1251	    const width = this.width + this.strokeWidth,
1252	      height = this.height + this.strokeWidth,
1253	      pCanvas = createCanvasElementFor({
1254	        width,
1255	        height,
1256	      }),
1257	      pCtx = pCanvas.getContext('2d')!;
1258	    pCanvas.width = width;
1259	    pCanvas.height = height;
1260	    pCtx.beginPath();
1261	    pCtx.moveTo(0, 0);
1262	    pCtx.lineTo(width, 0);
1263	    pCtx.lineTo(width, height);
1264	    pCtx.lineTo(0, height);
1265	    pCtx.closePath();
1266	    pCtx.translate(width / 2, height / 2);
1267	    pCtx.fillStyle = filler.toLive(pCtx)!;
