const fs=require("fs");
function fns(s){
  // match "  name(" or "  name = (" style methods and standalone functions
  const map={};
  const re=/\n(?:  |function )([a-zA-Z_$][\w$]*)\s*\(/g;let m;
  while((m=re.exec(s))){
    const name=m[1];
    let i=s.indexOf("{",m.index);if(i<0)continue;
    // ensure the { is the body (skip if next real char after ) chain)
    let d=0,j=i;for(;j<s.length;j++){if(s[j]=="{")d++;else if(s[j]=="}"){d--;if(d==0){j++;break}}}
    const body=s.slice(i,j);
    if(!map[name])map[name]=[];map[name].push(body);
  }
  return map;
}
const P=fns(fs.readFileSync("/tmp/pristine.mjs","utf8"));
const B=fns(fs.readFileSync("/tmp/built_buggy.mjs","utf8"));
function norm(x){return x.replace(/\/\*[\s\S]*?\*\//g,"").replace(/\/\/[^\n]*/g,"").replace(/\s+/g,"");}
const all=new Set([...Object.keys(P),...Object.keys(B)]);
for(const n of all){
  const pa=(P[n]||[]).map(norm), ba=(B[n]||[]).map(norm);
  // compare as multisets
  const ps=[...pa].sort().join("|"), bs=[...ba].sort().join("|");
  if(ps!==bs){
    // ignore pure Map-refactor noise: skip if diff only involves .has/.get/.set vs [ ]
    console.log("FNDIFF",n,"(count p="+pa.length+" b="+ba.length+")");
  }
}
