cd /app
cat > /app/analyze.mjs <<'EOF'
import { loadImage, createCanvas } from 'canvas';
for (const n of ['bug_1','expected']) {
  const img = await loadImage(`/app/.harbor_assets/${n}.png`);
  const c = createCanvas(img.width, img.height);
  const ctx = c.getContext('2d');
  ctx.drawImage(img,0,0);
  const {data,width,height}=ctx.getImageData(0,0,img.width,img.height);
  // column darkness
  const cols=[];
  for(let x=0;x<width;x++){let d=0;for(let y=0;y<height;y++){const i=(y*width+x)*4;if(data[i]<128)d++;}cols.push(d);}
  // find runs of dark columns
  let runs=[],inRun=false,start=0;
  for(let x=0;x<width;x++){const dark=cols[x]>0;if(dark&&!inRun){inRun=true;start=x;}else if(!dark&&inRun){inRun=false;runs.push([start,x-1]);}}
  if(inRun)runs.push([start,width-1]);
  console.log(n, img.width+'x'+img.height, 'dark column runs:', JSON.stringify(runs));
  // rows too
  const rows=[];for(let y=0;y<height;y++){let d=0;for(let x=0;x<width;x++){const i=(y*width+x)*4;if(data[i]<128)d++;}rows.push(d);}
  let rr=[],ir=false,rs=0;for(let y=0;y<height;y++){const dk=rows[y]>0;if(dk&&!ir){ir=true;rs=y;}else if(!dk&&ir){ir=false;rr.push([rs,y-1]);}}if(ir)rr.push([rs,height-1]);
  console.log('   dark row runs:', JSON.stringify(rr));
}
EOF
node /app/analyze.mjs

