254	   * determine if it is a reference or a new one.
255	   * @TODO this should always return a reference or always a clone or undefined when necessary.
256	   * @protected
257	   * @param {Number} lineIndex
258	   * @param {Number} charIndex
259	   * @return {TextStyleDeclaration} a style object reference to the existing one or a new empty object when undefined
260	   */
261	  _getStyleDeclaration(
262	    lineIndex: number,
