149	  /**
150	   * Generate an object that translates the style object so that it is
151	   * broken up by visual lines (new lines and automatic wrapping).
152	   * The original text styles object is broken up by actual lines (new lines only),
153	   * which is only sufficient for Text / IText
154	   * @private
155	   */
156	  _generateStyleMap(textInfo: TextLinesInfo): StyleMap {
157	    let realLineCount = 0,
158	      realLineCharCount = 0,
159	      charCount = 0;
160	    const map: StyleMap = {};
161	
162	    for (let i = 0; i < textInfo.graphemeLines.length; i++) {
163	      if (textInfo.graphemeText[charCount] === '\n' && i > 0) {
164	        realLineCharCount = 0;
165	        charCount++;
166	        realLineCount++;
167	      } else if (
168	        !this.splitByGrapheme &&
169	        this._reSpaceAndTab.test(textInfo.graphemeText[charCount]) &&
