333	  /**
334	   * For each line of text terminated by an hard line stop,
335	   * measure each word width and extract the largest word from all.
336	   * The returned words here are the one that at the end will be rendered.
337	   * @param {string[]} lines the lines we need to measure
338	   *
339	   */
340	  getGraphemeDataForRender(lines: string[]): GraphemeData {
341	    const splitByGrapheme = this.splitByGrapheme,
342	      infix = splitByGrapheme ? '' : ' ';
343	
344	    let largestWordWidth = 0;
345	
346	    const data = lines.map((line, lineIndex) => {
347	      let offset = 0;
348	      const wordsOrGraphemes = splitByGrapheme
349	        ? this.graphemeSplit(line)
350	        : this.wordSplit(line);
351	
352	      if (wordsOrGraphemes.length === 0) {
353	        return [{ word: [], width: 0 }];
354	      }
355	
356	      return wordsOrGraphemes.map((word: string) => {
357	        // if using splitByGrapheme words are already in graphemes.
358	        const graphemeArray = splitByGrapheme
359	          ? [word]
360	          : this.graphemeSplit(word);
361	        const width = this._measureWord(graphemeArray, lineIndex, offset);
362	        largestWordWidth = Math.max(width, largestWordWidth);
363	        offset += graphemeArray.length + infix.length;
364	        return { word: graphemeArray, width };
365	      });
366	    });
367	
368	    return {
369	      wordsData: data,
370	      largestWordWidth,
371	    };
