374	  /**
375	   * Helper function to measure a string of text, given its lineIndex and charIndex offset
376	   * It gets called when charBounds are not available yet.
377	   * Override if necessary
378	   * Use with {@link Textbox#wordSplit}
379	   *
380	   * @param {CanvasRenderingContext2D} ctx
381	   * @param {String} text
382	   * @param {number} lineIndex
383	   * @param {number} charOffset
384	   * @returns {number}
385	   */
386	  _measureWord(word: string[], lineIndex: number, charOffset = 0): number {
387	    let width = 0,
388	      prevGrapheme;
389	    const skipLeft = true;
390	    for (let i = 0, len = word.length; i < len; i++) {
391	      const box = this._getGraphemeBox(
392	        word[i],
393	        lineIndex,
394	        i + charOffset,
395	        prevGrapheme,
396	        skipLeft,
397	      );
398	      width += box.kernedWidth;
399	      prevGrapheme = word[i];
400	    }
401	    return width;
402	  }
