404	  /**
405	   * Override this method to customize word splitting
406	   * Use with {@link Textbox#_measureWord}
407	   * @param {string} value
408	   * @returns {string[]} array of words
409	   */
410	  wordSplit(value: string): string[] {
411	    return value.split(this._wordJoiners);
412	  }
413	
414	  /**
415	   * Wraps a line of text using the width of the Textbox as desiredWidth
416	   * and leveraging the known width o words from GraphemeData
417	   * @private
418	   * @param {Number} lineIndex
419	   * @param {Number} desiredWidth width you want to wrap the line to
420	   * @param {GraphemeData} graphemeData an object containing all the lines' words width.
421	   * @param {Number} reservedSpace space to remove from wrapping for custom functionalities
422	   * @returns {Array} Array of line(s) into which the given text is wrapped
423	   * to.
424	   */
425	  _wrapLine(
426	    lineIndex: number,
427	    desiredWidth: number,
428	    { largestWordWidth, wordsData }: GraphemeData,
429	    reservedSpace = 0,
430	  ): string[][] {
431	    const additionalSpace = this._getWidthOfCharSpacing(),
432	      splitByGrapheme = this.splitByGrapheme,
433	      graphemeLines = [],
434	      infix = splitByGrapheme ? '' : ' ';
435	
436	    let lineWidth = 0,
437	      line: string[] = [],
438	      // spaces in different languages?
439	      offset = 0,
440	      infixWidth = 0,
441	      lineJustStarted = true;
442	
443	    desiredWidth -= reservedSpace;
444	
445	    const maxWidth = Math.max(
446	      desiredWidth,
447	      largestWordWidth,
448	      this.dynamicMinWidth,
449	    );
450	    // layout words
451	    const data = wordsData[lineIndex];
452	    offset = 0;
453	    let i;
454	    for (i = 0; i < data.length; i++) {
455	      const { word, width: wordWidth } = data[i];
456	      offset += word.length;
457	
458	      lineWidth += infixWidth + wordWidth - additionalSpace;
459	      if (lineWidth > maxWidth && !lineJustStarted) {
460	        graphemeLines.push(line);
461	        line = [];
462	        lineWidth = wordWidth;
463	        lineJustStarted = true;
464	      } else {
465	        lineWidth += additionalSpace;
466	      }
467	
468	      if (!lineJustStarted && !splitByGrapheme) {
469	        line.push(infix);
470	      }
471	      line = line.concat(word);
472	
473	      infixWidth = splitByGrapheme
474	        ? 0
475	        : this._measureWord([infix], lineIndex, offset);
476	      offset++;
477	      lineJustStarted = false;
478	    }
479	
480	    i && graphemeLines.push(line);
481	
482	    // TODO: this code is probably not necessary anymore.
483	    // it can be moved out of this function since largestWordWidth is now
484	    // known in advance
485	    if (largestWordWidth + reservedSpace > this.dynamicMinWidth) {
486	      this.dynamicMinWidth = largestWordWidth - additionalSpace + reservedSpace;
487	    }
488	    return graphemeLines;
489	  }
490	
491	  /**
492	   * Detect if the text line is ended with an hard break
493	   * text and itext do not have wrapping, return false
494	   * @param {Number} lineIndex text to split
495	   * @return {Boolean}
496	   */
497	  isEndOfWrapping(lineIndex: number): boolean {
498	    if (!this._styleMap[lineIndex + 1]) {
499	      // is last line, return true;
500	      return true;
501	    }
502	    if (this._styleMap[lineIndex + 1].line !== this._styleMap[lineIndex].line) {
503	      // this is last line before a line break, return true;
504	      return true;
505	    }
506	    return false;
507	  }
508	
509	  /**
510	   * Detect if a line has a linebreak and so we need to account for it when moving
511	   * and counting style.
512	   * This is important only for splitByGrapheme at the end of wrapping.
513	   * If we are not wrapping the offset is always 1
514	   * @return Number
515	   */
516	  missingNewlineOffset(lineIndex: number, skipWrapping?: boolean): 0 | 1 {
517	    if (this.splitByGrapheme && !skipWrapping) {
518	      return this.isEndOfWrapping(lineIndex) ? 1 : 0;
519	    }
520	    return 1;
521	  }
522	
523	  /**
524	   * Gets lines of text to render in the Textbox. This function calculates
525	   * text wrapping on the fly every time it is called.
526	   * @param {String} text text to split
527	   * @returns {Array} Array of lines in the Textbox.
528	   * @override
529	   */
530	  _splitTextIntoLines(text: string) {
531	    const newText = super._splitTextIntoLines(text),
532	      graphemeLines = this._wrapText(newText.lines, this.width),
533	      lines = new Array(graphemeLines.length);
534	    for (let i = 0; i < graphemeLines.length; i++) {
535	      lines[i] = graphemeLines[i].join('');
536	    }
537	    newText.lines = lines;
538	    newText.graphemeLines = graphemeLines;
539	    return newText;
540	  }
