546	  _removeExtraneousStyles() {
547	    const linesToKeep = new Map();
548	    for (const prop in this._styleMap) {
549	      const propNumber = parseInt(prop, 10);
550	      if (this._textLines[propNumber]) {
551	        const lineIndex = this._styleMap[prop].line;
552	        linesToKeep.set(`${lineIndex}`, true);
553	      }
554	    }
555	    for (const prop in this.styles) {
556	      if (!linesToKeep.has(prop)) {
557	        delete this.styles[prop];
558	      }
559	    }
560	  }
