562	  /**
563	   * Returns object representation of an instance
564	   * @param {Array} [propertiesToInclude] Any properties that you might want to additionally include in the output
565	   * @return {Object} object representation of an instance
566	   */
567	  toObject<
568	    T extends Omit<Props & TClassProperties<this>, keyof SProps>,
569	    K extends keyof T = never,
570	  >(propertiesToInclude: K[] = []): Pick<T, K> & SProps {
571	    return super.toObject<T, K>([
572	      'minWidth',
573	      'splitByGrapheme',
574	      ...propertiesToInclude,
575	    ] as K[]);
576	  }
577	}
