495	   * @return {Boolean}
496	   */
497	  isEndOfWrapping(lineIndex: number): boolean {
498	    if (!this._styleMap[lineIndex + 1]) {
499	      // is last line, return true;
500	      return true;
501	    }
502	    if (this._styleMap[lineIndex + 1].line !== this._styleMap[lineIndex].line) {
503	      // this is last line before a line break, return true;
504	      return true;
505	    }
506	    return false;
507	  }
508	
509	  /**
510	   * Detect if a line has a linebreak and so we need to account for it when moving
511	   * and counting style.
512	   * This is important only for splitByGrapheme at the end of wrapping.
513	   * If we are not wrapping the offset is always 1
514	   * @return Number
515	   */
516	  missingNewlineOffset(lineIndex: number, skipWrapping?: boolean): 0 | 1 {
517	    if (this.splitByGrapheme && !skipWrapping) {
518	      return this.isEndOfWrapping(lineIndex) ? 1 : 0;
519	    }
520	    return 1;
521	  }
522	
523	  /**
524	   * Gets lines of text to render in the Textbox. This function calculates
525	   * text wrapping on the fly every time it is called.
526	   * @param {String} text text to split
527	   * @returns {Array} Array of lines in the Textbox.
528	   * @override
529	   */
530	  _splitTextIntoLines(text: string) {
531	    const newText = super._splitTextIntoLines(text),
532	      graphemeLines = this._wrapText(newText.lines, this.width),
533	      lines = new Array(graphemeLines.length);
534	    for (let i = 0; i < graphemeLines.length; i++) {
535	      lines[i] = graphemeLines[i].join('');
536	    }
537	    newText.lines = lines;
538	    newText.graphemeLines = graphemeLines;
539	    return newText;
540	  }
