import { describe, expect, it } from 'vitest';
import { StaticCanvas } from '../canvas/StaticCanvas';
import { FabricText } from './Text/Text';

describe('bug repro render', () => {
  it('renders two multiline texts', () => {
    const canvas = new StaticCanvas(undefined, { width: 400, height: 200 });
    const t1 = new FabricText('a\nb', { left: 50, top: 50, fontSize: 30 });
    const t2 = new FabricText('c\nd', { left: 150, top: 50, fontSize: 30 });
    canvas.add(t1, t2);
    canvas.renderAll();
    console.log('T1', t1.width, t1.height, 'zoom', t1.zoomX, t1.zoomY);
    console.log('T2', t2.width, t2.height, 'zoom', t2.zoomX, t2.zoomY);
    const ctx = (canvas.lowerCanvasEl as any).getContext('2d');
    const { data, width, height } = ctx.getImageData(0, 0, 400, 200);
    // build ascii at 40x20
    let out = '';
    for (let gy = 0; gy < 20; gy++) {
      for (let gx = 0; gx < 40; gx++) {
        let dark = false;
        for (let py = gy * 10; py < gy * 10 + 10 && !dark; py++) {
          for (let px = gx * 10; px < gx * 10 + 10; px++) {
            const idx = (py * width + px) * 4;
            if (data[idx + 3] > 20 && data[idx] < 200) {
              dark = true;
              break;
            }
          }
        }
        out += dark ? '#' : '.';
      }
      out += '\n';
    }
    console.log(out);
    expect(true).toBe(true);
  });
});

