import { createCanvas, loadImage } from 'canvas';
for (const f of ['bug_1','expected']) {
  const img = await loadImage(`/app/.harbor_assets/${f}.png`);
  const c = createCanvas(img.width, img.height);
  const ctx = c.getContext('2d');
  ctx.drawImage(img,0,0);
  const {data} = ctx.getImageData(0,0,img.width,img.height);
  // find dark pixel bounding boxes via column/row projections
  const W=img.width,H=img.height;
  let minx=W,maxx=0,miny=H,maxy=0;
  const cols=new Array(W).fill(0), rows=new Array(H).fill(0);
  for(let y=0;y<H;y++)for(let x=0;x<W;x++){const i=(y*W+x)*4; if(data[i+3]>30&&data[i]<180){cols[x]++;rows[y]++; if(x<minx)minx=x;if(x>maxx)maxx=x;if(y<miny)miny=y;if(y>maxy)maxy=y;}}
  console.log(f, 'size',W,H,'bbox x',minx,maxx,'y',miny,maxy);
  // column runs (find x clusters)
  let runs=[];let s=-1;
  for(let x=0;x<W;x++){ if(cols[x]>0){ if(s<0)s=x;} else { if(s>=0){runs.push([s,x-1]);s=-1;} } }
  if(s>=0)runs.push([s,W-1]);
  console.log('  x-clusters:', runs.map(r=>r.join('-')).join(', '));
  let rr=[];s=-1;
  for(let y=0;y<H;y++){ if(rows[y]>0){ if(s<0)s=y;} else { if(s>=0){rr.push([s,y-1]);s=-1;} } }
  if(s>=0)rr.push([s,H-1]);
  console.log('  y-clusters:', rr.map(r=>r.join('-')).join(', '));
}
EOF
