import { createCanvas, registerFont, loadImage } from 'canvas';
import path from 'node:path';

const dir = path.resolve('./test/fixtures');
for (const [f, w, s] of [
  ['Ubuntu-Regular.ttf', 'regular', 'normal'],
  ['Ubuntu-Bold.ttf', 'bold', 'normal'],
  ['Ubuntu-Italic.ttf', 'regular', 'italic'],
  ['Ubuntu-BoldItalic.ttf', 'bold', 'italic'],
]) {
  registerFont(path.join(dir, f), { family: 'Ubuntu', weight: w, style: s });
}

const fabric = await import('./dist/index.node.mjs');
const { renderTests } = await import('./e2e/tests/visual-output/rendering/testcases/text.ts').catch(async () => {
  // ts can't be imported directly; fallback below
  return {};
});

// We'll instead import the compiled testcases via tsx-like transform is unavailable.
// So inline: we read renderingCases through a dynamic approach is hard. Instead just handle text.ts cases manually.
console.log('fabric loaded', !!fabric.FabricText, 'tests', renderTests?.length);

