import { createCanvas, registerFont } from 'canvas';
import path from 'node:path';
const dir = path.resolve('./test/fixtures');
for (const [f,w,s] of [['Ubuntu-Regular.ttf','regular','normal'],['Ubuntu-Bold.ttf','bold','normal'],['Ubuntu-Italic.ttf','regular','italic'],['Ubuntu-BoldItalic.ttf','bold','italic']])
  registerFont(path.join(dir,f),{family:'Ubuntu',weight:w,style:s});

const src = await import('./dist/index.node.mjs');
const pri = await import('./_pristine.node.mjs');

function snap(fabric) {
  const out = {};
  const F = fabric.FabricText, IT = fabric.IText, TB = fabric.Textbox;
  const cases = [
    ['t-basic', () => new F('hello world')],
    ['t-multi', () => new F('a\nbb\nccc')],
    ['t-empty', () => new F('')],
    ['t-emptylines', () => new F('a\n\n\nb')],
    ['t-right', () => new F('a\nbbbb', {textAlign:'right'})],
    ['t-center', () => new F('a\nbbbb', {textAlign:'center'})],
    ['t-justify', () => new F('a b c d\ne f', {textAlign:'justify'})],
    ['t-charspacing', () => new F('hello\nworld', {charSpacing:200})],
    ['t-styles', () => new F('hello', {styles:{0:{0:{fontSize:60},1:{fill:'red'}}}})],
    ['t-lineheight', () => new F('a\nb\nc', {lineHeight:2})],
    ['t-font', () => new F('hello world', {fontFamily:'Ubuntu', fontSize:33})],
    ['it-basic', () => new IT('hello\nworld')],
    ['tb-wrap', () => new TB('the quick brown fox jumps over', {width:100})],
