import { createCanvas, registerFont } from 'canvas';
import path from 'node:path';
const dir = path.resolve('./test/fixtures');
for (const [f,w,s] of [['Ubuntu-Regular.ttf','regular','normal'],['Ubuntu-Bold.ttf','bold','normal'],['Ubuntu-Italic.ttf','regular','italic'],['Ubuntu-BoldItalic.ttf','bold','italic']])
  registerFont(path.join(dir,f),{family:'Ubuntu',weight:w,style:s});

const src = await import('./dist/index.node.mjs');
const pri = await import('./_pristine.node.mjs');

function render(fabric, mk, W, H) {
  const canvas = new fabric.StaticCanvas(null, {width:W, height:H, renderOnAddRemove:false});
  canvas.backgroundColor = 'white';
  fabric.FabricObject.ownDefaults.objectCaching = false;
  mk(canvas, fabric);
  canvas.renderAll();
  return canvas.getElement().getContext('2d').getImageData(0,0,W,H).data;
}

const scenarios = [
  ['two-multiline', (c,f)=>{ c.add(new f.FabricText('a\nb',{left:20,top:20,fontSize:30}), new f.FabricText('c\nd',{left:100,top:20,fontSize:30})); }, 200,120],
  ['two-multiline-font', (c,f)=>{ c.add(new f.FabricText('Hello\nWorld',{left:10,top:10,fontFamily:'Ubuntu',fontSize:24}), new f.FabricText('Foo\nBar\nBaz',{left:120,top:10,fontFamily:'Ubuntu',fontSize:24})); }, 260,140],
  ['textbox-two', (c,f)=>{ c.add(new f.Textbox('the quick brown fox',{left:10,top:10,width:80}), new f.Textbox('lorem ipsum dolor',{left:110,top:10,width:80})); }, 220,180],
  ['itext-two', (c,f)=>{ c.add(new f.IText('one\ntwo',{left:10,top:10}), new f.IText('three\nfour',{left:120,top:10})); }, 260,120],
  ['styled-multiline', (c,f)=>{ c.add(new f.FabricText('AB\nCD',{left:10,top:10,fontSize:40,styles:{0:{0:{fill:'red',fontSize:60}}}})); }, 150,150],
  ['align-right', (c,f)=>{ c.add(new f.FabricText('a\nbbbbb\ncc',{left:10,top:10,textAlign:'right',fontSize:30})); }, 200,150],
  ['justify', (c,f)=>{ c.add(new f.FabricText('a b c d e\nf g',{left:10,top:10,textAlign:'justify',fontSize:24,width:180})); }, 220,120],
  ['charspacing', (c,f)=>{ c.add(new f.FabricText('spacing\ntest',{left:10,top:10,charSpacing:300,fontSize:24})); }, 260,120],
];

for (const [name, mk, W, H] of scenarios) {
  const a = render(src, mk, W, H), b = render(pri, mk, W, H);
  let diff = 0;
  for (let i=0;i<a.length;i+=4) {
    if (Math.abs(a[i]-b[i])+Math.abs(a[i+1]-b[i+1])+Math.abs(a[i+2]-b[i+2])+Math.abs(a[i+3]-b[i+3]) > 10) diff++;
  }
  console.log(`${name.padEnd(20)} diffpx=${diff} / ${W*H}`);
}

