import { describe, expect, it } from 'vitest';
import { FabricText } from './Text/Text';
import { IText } from './IText/IText';
import { Textbox } from './Textbox';

describe('bug scan', () => {
  it('various', () => {
    const mk = (label: string, o: any) =>
      console.log(label, 'w=', o.width.toFixed(2), 'h=', o.height.toFixed(2));
    mk('T1 a\\nb', new FabricText('a\nb'));
    mk('T2 a\\nb again', new FabricText('a\nb'));
    mk('T same string', new FabricText('same\nstring'));
    mk('T same string 2', new FabricText('same\nstring'));
    mk('IText', new IText('hello\nworld'));
    mk('IText 2', new IText('hello\nworld'));
    mk('Textbox', new Textbox('hello world foo bar baz', { width: 80 }));
