    mk('T empty lines', new FabricText('a\n\nb'));
    mk('T charSpacing', new FabricText('a\nb', { charSpacing: 500 }));
    mk('T justify', new FabricText('a b c\nd e f', { textAlign: 'justify' }));
  });
});

