19	  [line: number | string]: { [char: number | string]: TextStyleDeclaration };
20	};
21	
22	export abstract class StyledText<
23	  Props extends TOptions<FabricObjectProps> = Partial<FabricObjectProps>,
24	  SProps extends SerializedObjectProps = SerializedObjectProps,
25	  EventSpec extends ObjectEvents = ObjectEvents,
26	> extends FabricObject<Props, SProps, EventSpec> {
27	  declare abstract styles: TextStyle;
28	  declare protected abstract _textLines: string[][];
29	  declare protected _forceClearCache: boolean;
30	  static _styleProperties: Readonly<StylePropertiesType[]> = styleProperties;
31	  abstract get2DCursorLocation(
32	    selectionStart: number,
33	    skipWrapping?: boolean,
34	  ): { charIndex: number; lineIndex: number };
35	
36	  /**
37	   * Returns true if object has no styling or no styling in a line
38	   * @param {Number} lineIndex , lineIndex is on wrapped lines.
39	   * @return {Boolean}
40	   */
41	  isEmptyStyles(lineIndex?: number): boolean {
42	    if (!this.styles) {
43	      return true;
44	    }
45	    if (typeof lineIndex !== 'undefined' && !this.styles[lineIndex]) {
46	      return true;
47	    }
48	    const obj =
49	      typeof lineIndex === 'undefined'
50	        ? this.styles
51	        : { line: this.styles[lineIndex] };
52	    for (const p1 in obj) {
53	      for (const p2 in obj[p1]) {
54	        // eslint-disable-next-line no-unused-vars
55	        for (const p3 in obj[p1][p2]) {
56	          return false;
57	        }
58	      }
59	    }
60	    return true;
61	  }
62	
63	  /**
64	   * Returns true if object has a style property or has it ina specified line
65	   * This function is used to detect if a text will use a particular property or not.
66	   * @param {String} property to check for
67	   * @param {Number} lineIndex to check the style on
68	   * @return {Boolean}
69	   */
70	  styleHas(property: keyof TextStyleDeclaration, lineIndex?: number): boolean {
71	    if (!this.styles) {
72	      return false;
73	    }
74	    if (typeof lineIndex !== 'undefined' && !this.styles[lineIndex]) {
75	      return false;
76	    }
77	    const obj =
78	      typeof lineIndex === 'undefined'
79	        ? this.styles
80	        : { 0: this.styles[lineIndex] };
81	    // eslint-disable-next-line
82	    for (const p1 in obj) {
83	      // eslint-disable-next-line
84	      for (const p2 in obj[p1]) {
85	        if (typeof obj[p1][p2][property] !== 'undefined') {
86	          return true;
87	        }
88	      }
89	    }
90	    return false;
91	  }
92	
93	  /**
94	   * Check if characters in a text have a value for a property
95	   * whose value matches the textbox's value for that property.  If so,
96	   * the character-level property is deleted.  If the character
97	   * has no other properties, then it is also deleted.  Finally,
98	   * if the line containing that character has no other characters
99	   * then it also is deleted.
100	   */
101	  cleanStyle(property: keyof TextStyleDeclaration) {
102	    if (!this.styles) {
103	      return false;
104	    }
105	    const obj = this.styles;
106	    let stylesCount = 0,
107	      letterCount,
108	      stylePropertyValue,
109	      allStyleObjectPropertiesMatch = true,
110	      graphemeCount = 0;
111	    for (const p1 in obj) {
112	      letterCount = 0;
113	      for (const p2 in obj[p1]) {
114	        const styleObject = obj[p1][p2] || {},
115	          stylePropertyHasBeenSet = styleObject[property] !== undefined;
116	
117	        stylesCount++;
118	
119	        if (stylePropertyHasBeenSet) {
120	          if (!stylePropertyValue) {
121	            stylePropertyValue = styleObject[property];
122	          } else if (styleObject[property] !== stylePropertyValue) {
123	            allStyleObjectPropertiesMatch = false;
124	          }
125	
126	          if (styleObject[property] === this[property as keyof this]) {
127	            delete styleObject[property];
128	          }
129	        } else {
130	          allStyleObjectPropertiesMatch = false;
131	        }
132	
133	        if (Object.keys(styleObject).length !== 0) {
134	          letterCount++;
135	        } else {
136	          delete obj[p1][p2];
137	        }
138	      }
139	
140	      if (letterCount === 0) {
141	        delete obj[p1];
142	      }
143	    }
144	    // if every grapheme has the same style set then
145	    // delete those styles and set it on the parent
146	    for (let i = 0; i < this._textLines.length; i++) {
147	      graphemeCount += this._textLines[i].length;
148	    }
149	    if (allStyleObjectPropertiesMatch && stylesCount === graphemeCount) {
150	      this[property as keyof this] = stylePropertyValue as any;
151	      this.removeStyle(property);
152	    }
153	  }
154	
155	  /**
156	   * Remove a style property or properties from all individual character styles
157	   * in a text object.  Deletes the character style object if it contains no other style
158	   * props.  Deletes a line style object if it contains no other character styles.
159	   *
160	   * @param {String} props The property to remove from character styles.
161	   */
162	  removeStyle(property: keyof TextStyleDeclaration) {
163	    if (!this.styles) {
164	      return;
165	    }
166	    const obj = this.styles;
167	    let line, lineNum, charNum;
168	    for (lineNum in obj) {
169	      line = obj[lineNum];
170	      for (charNum in line) {
171	        delete line[charNum][property];
172	        if (Object.keys(line[charNum]).length === 0) {
173	          delete line[charNum];
174	        }
175	      }
176	      if (Object.keys(line).length === 0) {
177	        delete obj[lineNum];
178	      }
179	    }
180	  }
181	
182	  private _extendStyles(index: number, style: TextStyleDeclaration): void {
183	    const { lineIndex, charIndex } = this.get2DCursorLocation(index);
184	
185	    if (!this._getLineStyle(lineIndex)) {
186	      this._setLineStyle(lineIndex);
187	    }
188	
189	    const newStyle = pickBy(
190	      {
191	        // first create a new object that is a merge of existing and new
192	        ...this._getStyleDeclaration(lineIndex, charIndex),
193	        ...style,
194	        // use the predicate to discard undefined values
195	      },
196	      (value) => value !== undefined,
197	    );
198	
199	    // finally assign to the old position the new style
200	    this._setStyleDeclaration(lineIndex, charIndex, newStyle);
201	  }
202	
203	  /**
204	   * Gets style of a current selection/cursor (at the start position)
205	   * @param {Number} startIndex Start index to get styles at
206	   * @param {Number} endIndex End index to get styles at, if not specified startIndex + 1
207	   * @param {Boolean} [complete] get full style or not
208	   * @return {Array} styles an array with one, zero or more Style objects
209	   */
210	  getSelectionStyles(
211	    startIndex: number,
212	    endIndex?: number,
213	    complete?: boolean,
214	  ): TextStyleDeclaration[] {
215	    const styles: TextStyleDeclaration[] = [];
216	    for (let i = startIndex; i < (endIndex || startIndex); i++) {
217	      styles.push(this.getStyleAtPosition(i, complete));
218	    }
219	    return styles;
220	  }
221	
222	  /**
223	   * Gets style of a current selection/cursor position
224	   * @param {Number} position  to get styles at
225	   * @param {Boolean} [complete] full style if true
226	   * @return {Object} style Style object at a specified index
227	   * @private
228	   */
229	  getStyleAtPosition(position: number, complete?: boolean) {
230	    const { lineIndex, charIndex } = this.get2DCursorLocation(position);
231	    return complete
232	      ? this.getCompleteStyleDeclaration(lineIndex, charIndex)
233	      : this._getStyleDeclaration(lineIndex, charIndex);
234	  }
235	
236	  /**
237	   * Sets style of a current selection, if no selection exist, do not set anything.
238	   * @param {Object} styles Styles object
239	   * @param {Number} startIndex Start index to get styles at
240	   * @param {Number} [endIndex] End index to get styles at, if not specified startIndex + 1
241	   */
242	  setSelectionStyles(styles: object, startIndex: number, endIndex?: number) {
243	    for (let i = startIndex; i < (endIndex || startIndex); i++) {
244	      this._extendStyles(i, styles);
245	    }
246	    /* not included in _extendStyles to avoid clearing cache more than once */
247	    this._forceClearCache = true;
248	  }
249	
250	  /**
251	   * Get a reference, not a clone, to the style object for a given character,
252	   * if no style is set for a line or char, return a new empty object.
253	   * This is tricky and confusing because when you get an empty object you can't
254	   * determine if it is a reference or a new one.
255	   * @TODO this should always return a reference or always a clone or undefined when necessary.
256	   * @protected
257	   * @param {Number} lineIndex
258	   * @param {Number} charIndex
259	   * @return {TextStyleDeclaration} a style object reference to the existing one or a new empty object when undefined
260	   */
261	  _getStyleDeclaration(
262	    lineIndex: number,
263	    charIndex: number,
264	  ): TextStyleDeclaration {
265	    const lineStyle = this.styles && this.styles[lineIndex];
266	    return lineStyle ? (lineStyle[charIndex] ?? {}) : {};
267	  }
268	
269	  /**
270	   * return a new object that contains all the style property for a character
271	   * the object returned is newly created
272	   * @param {Number} lineIndex of the line where the character is
273	   * @param {Number} charIndex position of the character on the line
274	   * @return {Object} style object
275	   */
276	  getCompleteStyleDeclaration(
277	    lineIndex: number,
278	    charIndex: number,
279	  ): CompleteTextStyleDeclaration {
280	    return {
281	      ...pick(
282	        this,
283	        (this.constructor as typeof StyledText)
284	          ._styleProperties as (keyof this)[],
285	      ),
286	      ...this._getStyleDeclaration(lineIndex, charIndex),
287	    } as CompleteTextStyleDeclaration;
288	  }
289	
290	  /**
291	   * @param {Number} lineIndex
292	   * @param {Number} charIndex
293	   * @param {Object} style
294	   * @private
295	   */
296	  protected _setStyleDeclaration(
297	    lineIndex: number,
298	    charIndex: number,
299	    style: object,
300	  ) {
301	    this.styles[lineIndex][charIndex] = style;
302	  }
303	
304	  /**
305	   *
306	   * @param {Number} lineIndex
307	   * @param {Number} charIndex
308	   * @private
309	   */
310	  protected _deleteStyleDeclaration(lineIndex: number, charIndex: number) {
311	    delete this.styles[lineIndex][charIndex];
312	  }
313	
314	  /**
315	   * @param {Number} lineIndex
316	   * @return {Boolean} if the line exists or not
317	   * @private
318	   */
319	  protected _getLineStyle(lineIndex: number): boolean {
320	    return !!this.styles[lineIndex];
321	  }
322	
323	  /**
324	   * Set the line style to an empty object so that is initialized
325	   * @param {Number} lineIndex
326	   * @private
327	   */
328	  protected _setLineStyle(lineIndex: number) {
329	    this.styles[lineIndex] = {};
330	  }
331	
332	  protected _deleteLineStyle(lineIndex: number) {
333	    delete this.styles[lineIndex];
334	  }
335	}
