794	  /**
795	   * Execute the drawing operation for an object clipPath
796	   * @param {CanvasRenderingContext2D} ctx Context to render on
797	   * @param {FabricObject} clipPath
798	   */
799	  drawClipPathOnCache(
800	    ctx: CanvasRenderingContext2D,
801	    clipPath: FabricObject,
802	    canvasWithClipPath: HTMLCanvasElement,
803	  ) {
804	    ctx.save();
805	    // DEBUG: uncomment this line, comment the following
806	    // ctx.globalAlpha = 0.4
807	    if (clipPath.inverted) {
808	      ctx.globalCompositeOperation = 'destination-out';
809	    } else {
810	      ctx.globalCompositeOperation = 'destination-in';
811	    }
812	    ctx.setTransform(1, 0, 0, 1, 0, 0);
