820	   * @param {boolean} forClipping apply clipping styles
821	   * @param {DrawContext} context additional context for rendering
822	   */
823	  drawObject(
824	    ctx: CanvasRenderingContext2D,
825	    forClipping: boolean | undefined,
826	    context: DrawContext,
827	  ) {
828	    const originalFill = this.fill,
829	      originalStroke = this.stroke;
830	    if (forClipping) {
831	      this.fill = 'black';
832	      this.stroke = '';
833	      this._setClippingProperties(ctx);
834	    } else {
835	      this._renderBackground(ctx);
836	    }
837	    this._render(ctx);
838	    this._drawClipPath(ctx, this.clipPath, context);
839	    this.fill = originalFill;
840	    this.stroke = originalStroke;
841	  }
