891	   * @param {CanvasRenderingContext2D} ctx Context to render on
892	   */
893	  drawCacheOnCanvas(this: TCachedFabricObject, ctx: CanvasRenderingContext2D) {
894	    ctx.scale(1 / this.zoomX, 1 / this.zoomY);
895	    ctx.drawImage(
896	      this._cacheCanvas,
897	      -this.cacheTranslationX,
898	      -this.cacheTranslationY,
899	    );
900	  }
