1598	  // #region Object stacking methods
1599	
1600	  /**
1601	   * A reference to the parent of the object
1602	   * Used to keep the original parent ref when the object has been added to an ActiveSelection, hence loosing the `group` ref
1603	   */
1604	  declare parent?: Group;
1605	
1606	  /**
1607	   * Checks if object is descendant of target
1608	   * Should be used instead of {@link Group.contains} or {@link StaticCanvas.contains} for performance reasons
1609	   * @param {TAncestor} target
1610	   * @returns {boolean}
1611	   */
1612	  isDescendantOf(target: TAncestor): boolean {
1613	    const { parent, group } = this;
1614	    return (
1615	      parent === target ||
1616	      group === target ||
1617	      // walk up
1618	      (!!parent && parent.isDescendantOf(target)) ||
1619	      (!!group && group !== parent && group.isDescendantOf(target))
1620	    );
1621	  }
1622	
1623	  /**
1624	   * @returns {Ancestors} ancestors (excluding `ActiveSelection`) from bottom to top
1625	   */
1626	  getAncestors(): Ancestors {
1627	    const ancestors: TAncestor[] = [];
1628	    // eslint-disable-next-line @typescript-eslint/no-this-alias
1629	    let parent: TAncestor | undefined = this;
1630	    do {
1631	      parent = parent.parent;
1632	      parent && ancestors.push(parent);
1633	    } while (parent);
1634	    return ancestors as Ancestors;
1635	  }
1636	
1637	  /**
1638	   * Compare ancestors
1639	   *
1640	   * @param {StackedObject} other
1641	   * @returns {AncestryComparison} an object that represent the ancestry situation.
1642	   */
1643	  findCommonAncestors<T extends this>(other: T): AncestryComparison {
1644	    if (this === other) {
1645	      return {
1646	        fork: [],
1647	        otherFork: [],
1648	        common: [this, ...this.getAncestors()],
1649	      } as AncestryComparison;
1650	    }
1651	    const ancestors = this.getAncestors();
1652	    const otherAncestors = other.getAncestors();
1653	    //  if `this` has no ancestors and `this` is top ancestor of `other` we must handle the following case
1654	    if (
1655	      ancestors.length === 0 &&
1656	      otherAncestors.length > 0 &&
1657	      this === otherAncestors[otherAncestors.length - 1]
1658	    ) {
1659	      return {
1660	        fork: [],
1661	        otherFork: [
1662	          other,
1663	          ...otherAncestors.slice(0, otherAncestors.length - 1),
1664	        ],
1665	        common: [this],
1666	      } as AncestryComparison;
1667	    }
1668	    //  compare ancestors
1669	    for (let i = 0, ancestor; i < ancestors.length; i++) {
1670	      ancestor = ancestors[i];
1671	      if (ancestor === other) {
1672	        return {
1673	          fork: [this, ...ancestors.slice(0, i)],
1674	          otherFork: [],
1675	          common: ancestors.slice(i),
1676	        } as AncestryComparison;
1677	      }
1678	      for (let j = 0; j < otherAncestors.length; j++) {
1679	        if (this === otherAncestors[j]) {
1680	          return {
1681	            fork: [],
1682	            otherFork: [other, ...otherAncestors.slice(0, j)],
1683	            common: [this, ...ancestors],
1684	          } as AncestryComparison;
1685	        }
1686	        if (ancestor === otherAncestors[j]) {
1687	          return {
1688	            fork: [this, ...ancestors.slice(0, i)],
1689	            otherFork: [other, ...otherAncestors.slice(0, j)],
1690	            common: ancestors.slice(i),
1691	          } as AncestryComparison;
1692	        }
1693	      }
1694	    }
1695	    // nothing shared
1696	    return {
1697	      fork: [this, ...ancestors],
1698	      otherFork: [other, ...otherAncestors],
1699	      common: [],
1700	    } as AncestryComparison;
1701	  }
1702	
1703	  /**
1704	   *
1705	   * @param {StackedObject} other
1706	   * @returns {boolean}
1707	   */
1708	  hasCommonAncestors<T extends this>(other: T): boolean {
1709	    const commonAncestors = this.findCommonAncestors(other);
1710	    return commonAncestors && !!commonAncestors.common.length;
1711	  }
1712	
1713	  /**
1714	   *
1715	   * @param {FabricObject} other object to compare against
1716	   * @returns {boolean | undefined} if objects do not share a common ancestor or they are strictly equal it is impossible to determine which is in front of the other; in such cases the function returns `undefined`
1717	   */
1718	  isInFrontOf<T extends this>(other: T): boolean | undefined {
1719	    if (this === other) {
1720	      return undefined;
1721	    }
1722	    const ancestorData = this.findCommonAncestors(other);
1723	
1724	    if (ancestorData.fork.includes(other as any)) {
1725	      return true;
1726	    }
1727	    if (ancestorData.otherFork.includes(this as any)) {
1728	      return false;
1729	    }
1730	    // if there isn't a common ancestor, we take the canvas.
1731	    // if there is no canvas, there is nothing to compare
1732	    const firstCommonAncestor = ancestorData.common[0] || this.canvas;
1733	    if (!firstCommonAncestor) {
1734	      return undefined;
1735	    }
1736	    const headOfFork = ancestorData.fork.pop(),
1737	      headOfOtherFork = ancestorData.otherFork.pop(),
1738	      thisIndex = (firstCommonAncestor as TCollection)._objects.indexOf(
1739	        headOfFork as any,
1740	      ),
1741	      otherIndex = (firstCommonAncestor as TCollection)._objects.indexOf(
1742	        headOfOtherFork as any,
1743	      );
1744	    return thisIndex > -1 && thisIndex > otherIndex;
1745	  }
