1758	   */
1759	  toObject(propertiesToInclude: any[] = []): any {
1760	    const propertiesToSerialize = propertiesToInclude.concat(
1761	      FabricObject.customProperties,
1762	      (this.constructor as typeof FabricObject).customProperties || [],
1763	    );
1764	    let clipPathData: Partial<SerializedObjectProps> | undefined;
1765	    const NUM_FRACTION_DIGITS = config.NUM_FRACTION_DIGITS;
1766	    const {
1767	      clipPath,
1768	      fill,
1769	      stroke,
1770	      shadow,
1771	      strokeDashArray,
1772	      left,
1773	      top,
1774	      originX,
1775	      originY,
1776	      width,
1777	      height,
1778	      strokeWidth,
1779	      strokeLineCap,
1780	      strokeDashOffset,
1781	      strokeLineJoin,
1782	      strokeUniform,
1783	      strokeMiterLimit,
1784	      scaleX,
1785	      scaleY,
1786	      angle,
1787	      flipX,
1788	      flipY,
1789	      opacity,
1790	      visible,
1791	      backgroundColor,
1792	      fillRule,
1793	      paintFirst,
1794	      globalCompositeOperation,
1795	      skewX,
1796	      skewY,
