1800	        propertiesToSerialize.concat('inverted', 'absolutePositioned'),
1801	      );
1802	    }
1803	    const toFixedBound = (val: number) => toFixed(val, NUM_FRACTION_DIGITS);
1804	    const object = {
1805	      ...pick(this, propertiesToSerialize as (keyof this)[]),
1806	      type: (this.constructor as typeof FabricObject).type,
1807	      version: VERSION,
1808	      originX,
1809	      originY,
1810	      left: toFixedBound(left),
1811	      top: toFixedBound(top),
1812	      width: toFixedBound(width),
1813	      height: toFixedBound(height),
1814	      fill: isSerializableFiller(fill) ? fill.toObject() : fill,
1815	      stroke: isSerializableFiller(stroke) ? stroke.toObject() : stroke,
1816	      strokeWidth: toFixedBound(strokeWidth),
1817	      strokeDashArray: strokeDashArray
1818	        ? strokeDashArray.concat()
1819	        : strokeDashArray,
1820	      strokeLineCap,
1821	      strokeDashOffset,
1822	      strokeLineJoin,
1823	      strokeUniform,
1824	      strokeMiterLimit: toFixedBound(strokeMiterLimit),
1825	      scaleX: toFixedBound(scaleX),
1826	      scaleY: toFixedBound(scaleY),
1827	      angle: toFixedBound(angle),
1828	      flipX,
1829	      flipY,
1830	      opacity: toFixedBound(opacity),
1831	      shadow: shadow ? shadow.toObject() : shadow,
1832	      visible,
1833	      backgroundColor,
1834	      fillRule,
1835	      paintFirst,
1836	      globalCompositeOperation,
1837	      skewX: toFixedBound(skewX),
1838	      skewY: toFixedBound(skewY),
1839	      ...(clipPathData ? { clipPath: clipPathData } : null),
1840	    };
1841	
1842	    return !this.includeDefaultValues
1843	      ? this._removeDefaultValues(object)
1844	      : object;
1845	  }
1846	
1847	  /**
1848	   * Returns (dataless) object representation of an instance
1849	   * @param {Array} [propertiesToInclude] Any properties that you might want to additionally include in the output
1850	   * @return {Object} Object representation of an instance
1851	   */
1852	  toDatalessObject(propertiesToInclude?: any[]): any {
1853	    // will be overwritten by subclasses
1854	    return this.toObject(propertiesToInclude);
1855	  }
1856	
1857	  /**
1858	   * @private
1859	   * @param {Object} object
1860	   */
1861	  _removeDefaultValues<T extends object>(object: T): Partial<T> {
1862	    // getDefaults() ( get from static ownDefaults ) should win over prototype since anyway they get assigned to instance
1863	    // ownDefault vs prototype is swappable only if you change all the fabric objects consistently.
1864	    const defaults = (this.constructor as typeof FabricObject).getDefaults();
1865	    const hasStaticDefaultValues = Object.keys(defaults).length > 0;
1866	    const baseValues = hasStaticDefaultValues
1867	      ? defaults
1868	      : Object.getPrototypeOf(this);
1869	
1870	    return pickBy(object, (value, key) => {
1871	      if (key === LEFT || key === TOP || key === 'type') {
1872	        return true;
1873	      }
1874	      const baseValue = baseValues[key];
1875	      return (
1876	        value !== baseValue &&
1877	        // basically a check for [] === []
1878	        !(
1879	          Array.isArray(value) &&
1880	          Array.isArray(baseValue) &&
1881	          value.length === 0 &&
1882	          baseValue.length === 0
1883	        )
1884	      );
1885	    });
1886	  }
1887	
1888	  /**
1889	   * Returns a string representation of an instance
1890	   * @return {String}
1891	   */
1892	  toString() {
1893	    return `#<${(this.constructor as typeof FabricObject).type}>`;
