1902	   * @param {AbortSignal} [options.signal] handle aborting, see https://developer.mozilla.org/en-US/docs/Web/API/AbortController/signal
1903	   * @returns {Promise<FabricObject>}
1904	   */
1905	  static _fromObject<S extends FabricObject>(
1906	    { type, ...serializedObjectOptions }: Record<string, unknown>,
1907	    { extraParam, ...options }: Abortable & { extraParam?: string } = {},
1908	  ): Promise<S> {
1909	    return enlivenObjectEnlivables<any>(serializedObjectOptions, options).then(
1910	      (enlivedObjectOptions) => {
1911	        // from the resulting enlived options, extract options.extraParam to arg0
1912	        // to avoid accidental overrides later
1913	        if (extraParam) {
1914	          delete enlivedObjectOptions[extraParam];
1915	          return new this(
1916	            serializedObjectOptions[extraParam],
1917	            // @ts-expect-error different signature
1918	            enlivedObjectOptions,
1919	          );
1920	        } else {
1921	          return new this(enlivedObjectOptions);
1922	        }
1923	      },
1924	    ) as Promise<S>;
1925	  }
1926	
1927	  /**
1928	   *
1929	   * @param {object} object
1930	   * @param {object} [options]
1931	   * @param {AbortSignal} [options.signal] handle aborting, see https://developer.mozilla.org/en-US/docs/Web/API/AbortController/signal
1932	   * @returns {Promise<FabricObject>}
1933	   */
1934	  static fromObject<T extends TOptions<SerializedObjectProps>>(
1935	    object: T,
1936	    options?: Abortable,
1937	  ) {
1938	    return this._fromObject(object, options);
1939	  }
